questionvariables.text:
/* 符号数の計算 AI 耐性用1題構成 */
/* v005 : 全体フィードバック (2023.6.19) */
stack_include("https://stack.mathedu.jp/sc/ky_linear_algebra.mac");
stack_include("https://stack.mathedu.jp/sc/multilang_library.mac");
sz:rand([4, 5, 6, 7]);
iv_min:[3, 4, 5, 6][sz-3];
%_iv(L):=inversion_number(L);
%_rp(L):=random_permutation(L);
nL:makelist(k, k, sz);
pL:%_rp(nL);
while (%_iv(pL)<iv_min) do pL:%_rp(nL);
iv:%_iv(pL);
ta1:((-1)^iv+3)/2;

makeQS(sz, p):=block([s, k], s:"", for k:1 thru sz do (s:sconcat(s, tex1(Wa[p[k]*10+k]))), return (s));
/* QSL:makelist(makeQS(szL[i], pnL[i]), i, 1, 4); */
QS:makeQS(sz, pL);

va1:makelist([k, if k=ta1 then true else false, if k=0 then "--" else [-1, 1][k]], k, 0, 2);
szS:sconcat("\\(", sz, "\\)");
qtext:%__lang([
["en", sconcat("When expanding the determinant of the square matrix of order ", szS, " \\(A=(a_{ij})\\), as a polynomial in its entries, determine the sign of the following term: \\(", QS, "\\)")],
["fr", sconcat("Lors du développement du déterminant de la matrice carrée d’ordre ", szS, ", \\(A=(a_{ij})\\), comme polynôme en ses coefficients, déterminez le signe du terme suivant : \\(", QS, "\\)")],
["de", sconcat("Beim Entwickeln der Determinante der quadratischen Matrix ", szS, "-ter Ordnung \\(A=(a_{ij})\\) als Polynom in ihren Einträgen, bestimmen Sie das Vorzeichen des folgenden Terms: \\(", QS, "\\)")],
["it", sconcat("Nello sviluppo del determinante della matrice quadrata di ordine ", szS, ", \\(A=(a_{ij})\\), come polinomio nelle sue componenti, determina il segno del seguente termine: \\(", QS, "\\)")],
["ja", sconcat(szS, "次正方行列\\(A=(a_{ij})\\)の行列式を成分に関する多項式として展開するとき, 次の項の符号を答えよ: \\(", QS, "\\)")]]);
